{# Sparkline: points mapped into a fixed chart box (110,560)-(970,880).
   min/max computed via namespace (plain {% set %} scoping doesn't stick
   across loop iterations) #}
{% set vals = slide.points | split(',') %}
{% set n = vals | length %}
{% set chart_x = 110 %}
{% set chart_w = 860 %}
{% set chart_top = 560 %}
{% set chart_h = 320 %}
{% set ns3 = namespace(max_v = 0, min_v = 999999) %}
{% for v in vals %}
  {% if v | float > ns3.max_v %}{% set ns3.max_v = v | float %}{% endif %}
  {% if v | float < ns3.min_v %}{% set ns3.min_v = v | float %}{% endif %}
{% endfor %}
{% set span = (ns3.max_v - ns3.min_v) if ns3.max_v > ns3.min_v else 1 %}
{% set step = chart_w / (n - 1) %}

{# Build the polyline points string + fill polygon via namespace concat #}
{% set ns = namespace(pts = "", first_y = 0, last_x = 0, last_y = 0) %}
{% for v in vals %}
  {% set x = chart_x + loop.index0 * step %}
  {% set y = chart_top + chart_h - ((v | float - ns3.min_v) * chart_h / span) %}
  {% if loop.first %}{% set ns.first_y = y %}{% endif %}
  {% set ns.last_x = x %}
  {% set ns.last_y = y %}
  {% set ns.pts = ns.pts ~ x | round(1) ~ "," ~ y | round(1) ~ " " %}
{% endfor %}








